<?php
require '../includes/header.php'; require '../includes/role_guard.php'; requireRole(['admin','staff','tribe_leader','tribe_rep']); require '../includes/db.php';
require_once '../includes/real_data_normalization.php'; require_once '../includes/family_access.php';
$q=trim((string)($_GET['q']??'')); $aff=(int)($_GET['affiliation']??0); $barangay=trim((string)($_GET['barangay']??'')); $scope=family_scope_tribe($conn);
$where=['1=1']; $params=[]; $types='';
if($scope!==null){$where[]='f.owning_tribe=?';$params[]=$scope;$types.='s';}
if($q!==''){$like="%$q%";$where[]="(h.first_name LIKE ? OR h.last_name LIKE ? OR s.first_name LIKE ? OR s.last_name LIKE ? OR a.name LIKE ? OR f.barangay LIKE ? OR f.sitio_street LIKE ? OR f.contact_number LIKE ? OR f.id_number LIKE ?)";for($i=0;$i<9;$i++)$params[]=$like;$types.='sssssssss';}
if($aff>0){$where[]='f.affiliation_id=?';$params[]=$aff;$types.='i';} if($barangay!==''){$where[]='f.barangay=?';$params[]=$barangay;$types.='s';}
$base=" FROM ip_families f LEFT JOIN ip_affiliations a ON a.id=f.affiliation_id LEFT JOIN ip_family_members h ON h.family_id=f.id AND h.member_role='head' LEFT JOIN ip_family_members s ON s.family_id=f.id AND s.member_role='spouse' WHERE ".implode(' AND ',$where);
$stmt=$conn->prepare('SELECT COUNT(*)'.$base); if($params)$stmt->bind_param($types,...$params);$stmt->execute();$total=(int)$stmt->get_result()->fetch_row()[0];[$page,$perPage,$offset,$pages]=pagination_values($total);
$stmt=$conn->prepare("SELECT f.id,f.family_reference,f.owning_tribe,f.barangay,f.sitio_street,f.contact_number,a.name affiliation_name,CONCAT_WS(' ',h.first_name,h.middle_name,h.last_name,h.suffix) head_name,CONCAT_WS(' ',s.first_name,s.middle_name,s.last_name,s.suffix) spouse_name,(SELECT COUNT(*) FROM ip_records r JOIN ip_family_members fm ON fm.id=r.family_member_id WHERE fm.family_id=f.id) record_count,(SELECT COUNT(DISTINCT cp.case_id) FROM case_persons_involved cp JOIN ip_family_members fm ON fm.id=cp.family_member_id WHERE fm.family_id=f.id) case_count,(SELECT COUNT(*) FROM tax_declarations td WHERE td.owner_family_id=f.id OR td.owner_family_member_id IN(SELECT id FROM ip_family_members WHERE family_id=f.id)) tax_count $base ORDER BY f.id DESC LIMIT $perPage OFFSET $offset");if($params)$stmt->bind_param($types,...$params);$stmt->execute();$families=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$affiliations=$conn->query("SELECT id,name FROM ip_affiliations WHERE status='active' ORDER BY name")->fetch_all(MYSQLI_ASSOC);$locations=$conn->query("SELECT DISTINCT barangay FROM ip_families WHERE barangay IS NOT NULL AND barangay<>'' ORDER BY barangay")->fetch_all(MYSQLI_ASSOC);
?>
<main class="main-no-right"><div class="page-heading"><div><h4>IP Family Registry</h4><p>Manage household records, heads of family, spouses, and affiliation information.</p></div><div class="d-flex gap-2"><?php if(($_SESSION['role']??'')==='admin'):?><a class="btn btn-light border" href="families/import.php"><i class="bi bi-file-earmark-spreadsheet me-1"></i>Import</a><?php endif;?><a class="btn btn-success" href="families/create.php"><i class="bi bi-plus-lg me-1"></i>New Family</a></div></div>
<form class="card-box mb-3" method="get"><div class="row g-2"><div class="col-lg-5"><label class="visually-hidden" for="familySearch">Search families</label><input id="familySearch" class="form-control" type="search" name="q" value="<?=e($q)?>" placeholder="Search head, spouse, contact, ID or location..."></div><div class="col-md-3"><select class="form-select" name="affiliation"><option value="">All affiliations</option><?php foreach($affiliations as $a):?><option value="<?=$a['id']?>" <?=$aff===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="barangay"><option value="">All barangays</option><?php foreach($locations as $l):?><option <?= $barangay===$l['barangay']?'selected':''?>><?=e($l['barangay'])?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex gap-1"><button class="btn btn-success flex-fill">Filter</button><a class="btn btn-light border" href="families.php" aria-label="Reset"><i class="bi bi-arrow-counterclockwise"></i></a></div></div></form>
<div class="card-box p-0 overflow-hidden"><table class="table table-hover align-middle"><thead><tr><th>Family / Head</th><th>Spouse</th><th>Affiliation</th><th>Location</th><th>Contact</th><th class="text-end">Action</th></tr></thead><tbody><?php if(!$families):?><tr><td colspan="6"><div class="empty-state border-0"><i class="bi bi-people"></i><h5>No family records found</h5><p>Adjust the filters or create the first family record.</p></div></td></tr><?php endif;?><?php foreach($families as $f):?><tr><td data-label="Family / Head"><strong><?=e(trim($f['head_name']))?></strong><small class="d-block text-muted"><?=e($f['family_reference'])?></small></td><td data-label="Spouse"><?=e(trim($f['spouse_name'])?:'—')?></td><td data-label="Affiliation"><?=e($f['affiliation_name']?:'Not recorded')?></td><td data-label="Location"><?=e(implode(', ',array_filter([$f['sitio_street'],$f['barangay']])))?></td><td data-label="Contact"><?=e($f['contact_number']?:'—')?></td><td class="text-end" data-label="Action"><a class="btn btn-sm btn-light border" href="families/view.php?id=<?=$f['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php render_pagination($page,$pages);?></main>
<?php require '../includes/footer.php';?>
